-- Migration 001: taxonomy / settings / catalog foundation (spec/03, TASK_003, DECISION_LOG D22).
-- Runs inside a runner-managed transaction. Do not edit after it has been applied: the runner checksums it.

CREATE TABLE schema_migrations (
  version     INTEGER PRIMARY KEY NOT NULL,
  checksum    TEXT NOT NULL,
  applied_at  TEXT NOT NULL,
  app_version TEXT NOT NULL
);

CREATE TABLE taxonomy_versions (
  id            TEXT PRIMARY KEY NOT NULL,
  version       TEXT NOT NULL UNIQUE,
  created_at    TEXT NOT NULL,
  manifest_hash TEXT NOT NULL
);

CREATE TABLE skills (
  id         TEXT PRIMARY KEY NOT NULL,
  created_at TEXT NOT NULL
);

CREATE TABLE skill_revisions (
  id              TEXT PRIMARY KEY NOT NULL,
  skill_id        TEXT NOT NULL REFERENCES skills(id) ON DELETE RESTRICT,
  taxonomy_id     TEXT NOT NULL REFERENCES taxonomy_versions(id) ON DELETE RESTRICT,
  parent_skill_id TEXT REFERENCES skills(id) ON DELETE RESTRICT,
  label_en        TEXT NOT NULL,
  domain          TEXT NOT NULL,
  family          TEXT NOT NULL,
  active          INTEGER NOT NULL CHECK (active IN (0, 1)),
  UNIQUE (skill_id, taxonomy_id)
);

CREATE TABLE learning_plans (
  id              TEXT PRIMARY KEY NOT NULL,
  revision        INTEGER NOT NULL UNIQUE CHECK (revision > 0),
  priorities_json TEXT NOT NULL CHECK (json_valid(priorities_json)),
  rationale       TEXT NOT NULL,
  reviewer        TEXT NOT NULL,
  created_at      TEXT NOT NULL,
  taxonomy_id     TEXT NOT NULL REFERENCES taxonomy_versions(id) ON DELETE RESTRICT
);

CREATE TABLE settings_revisions (
  id          TEXT PRIMARY KEY NOT NULL,
  revision    INTEGER NOT NULL UNIQUE CHECK (revision > 0),
  values_json TEXT NOT NULL CHECK (json_valid(values_json)),
  created_at  TEXT NOT NULL
);

